Here's a binary search implementation in Rust with documentation and unit tests:

```rust
/// Performs a binary search on a sorted vector of i32 values.
/// 
/// # Arguments
/// * `sorted_vec` - A reference to a sorted Vec<i32> (must be sorted in ascending order)
/// * `target` - The value to search for
/// 
/// # Returns
/// * `Some(index)` if the target is found, where index is the position in the vector
/// * `None` if the target is not present in the vector
/// 
/// # Complexity
/// * Time: O(log n)
/// * Space: O(1)
/// 
/// # Panics
/// * This function will not panic, but will return `None` if the vector is not sorted
/// 
/// # Example
/// ```
/// let vec = vec![1, 3, 5, 7, 9];
/// assert_eq!(binary_search(&vec, 5), Some(2));
/// assert_eq!(binary_search(&vec, 4), None);
/// ```
fn binary_search(sorted_vec: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = sorted_vec.len();

    while left < right {
        let mid = left + (right - left) / 2;

        if sorted_vec[mid] == target {
            return Some(mid);
        } else if sorted_vec[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
