```javascript
/**
 * Groups an array of objects by a specified key
 * @param {Array} array - The array of objects to group
 * @param {string} key - The key to group by
 * @returns {Object} - An object mapping each unique key value to an array of matching items
 */
function groupBy(array, key) {
  return array.reduce((result, item) => {
    // Get the value of the key for the current item
    const keyValue = item[key];

    // If the key doesn't exist yet in the result, create an empty array
    if (!result[keyValue]) {
      result[keyValue] = [];
    }

    // Add the current item to the appropriate group
    result[keyValue].push(item);

    return result;
  }, {});
}

