Here's a Go function that parses a simple key=value config file format:

```go
// ParseConfig parses a simple key=value configuration format.
//
// Expected format:
//   - One key=value pair per line
//   - Lines starting with '#' are treated as comments and ignored
//   - Blank lines are ignored
//   - Keys and values are trimmed of surrounding whitespace
//   - The first '=' in a line separates the key from the value
//   - Values may contain '=' characters (e.g., "url=http://example.com/path?x=1")
//   - Duplicate keys will overwrite previous values
//
// Returns a map containing the parsed key-value pairs.
func ParseConfig(data string) map[string]string {
	config := make(map[string]string)

	// Split the input into lines
	lines := strings.Split(data, "\n")

	for _, line := range lines {
		// Trim whitespace from the line
		line = strings.TrimSpace(line)

		// Skip blank lines and comments
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		// Find the first '=' character
		eqIndex := strings.Index(line, "=")
		if eqIndex == -1 {
			// No '=' found, skip this line (malformed)
			continue
		}

		// Extract key and value
		key := strings.TrimSpace(line[:eqIndex])
		value := strings.TrimSpace(line[eqIndex+1:])

		// Skip if key is empty
		if key == "" {
			continue
		}

		// Store in map
		config[key] = value
	}

	return config
}
```

