Here's a simple in-memory pub/sub class implementation in TypeScript:

```typescript
/**
 * A simple in-memory pub/sub (publish-subscribe) event system.
 * Allows subscribers to register callbacks for specific events and
 * publishers to broadcast data to all subscribers of that event.
 */
class PubSub {
  // Map to store event names and their associated subscriber callbacks
  private events: Map<string, Function[]> = new Map();

  /**
   * Subscribe a callback to a specific event
   * @param event - The event name to subscribe to
   * @param callback - The function to call when the event is published
   * @returns An unsubscribe function to remove the subscription
   */
  subscribe(event: string, callback: Function): () => void {
    // Get existing subscribers for this event, or create a new array
    const subscribers = this.events.get(event) || [];
    subscribers.push(callback);
    this.events.set(event, subscribers);

    // Return an unsubscribe function for easy cleanup
    return () => {
      const currentSubscribers = this.events.get(event);
      if (currentSubscribers) {
        const index = currentSubscribers.indexOf(callback);
        if (index > -1) {
          currentSubscribers.splice(index, 1);
          this.events.set(event, currentSubscribers);
        }
      }
    };
  }

  /**
   * Publish an event with data to all subscribers
   * @param event - The event name to publish
   * @param data - The data to pass to all subscriber callbacks
   */
  publish(event: string, data: any): void {
    const subscribers = this.events.get(event);
    if (subscribers) {
      // Call each subscriber with the published data
      subscribers.forEach(callback => callback(data));
    }
  }
}

// Example usage: Two subscribers receiving the same published event
const pubSub = new PubSub();

// First subscriber
const unsubscribe1 = pubSub.subscribe('userLogin', (user: { name: string }) => {
  console.log(`Subscriber 1: User ${user.name} logged in`);
});

// Second subscriber
const unsubscribe2 = pubSub.subscribe('userLogin', (user: { name: string }) => {
  console.log(`Subscriber 2: Welcome ${user.name}!`);
});

// Publish the event - both subscribers will receive it
pubSub.publish('userLogin', { name: 'Alice' });

// Output:
// Subscriber 1: User Alice logged in
// Subscriber 2: Welcome Alice!

// Optional: Unsubscribe if needed
// unsubscribe1();
// unsubscribe2();
```

**Key Features:**

1. **Type Safety**: Uses TypeScript's type system with proper annotations
2. **Flexible**: Can handle any event name and data type
3. **Cleanup**: Returns an unsubscribe function for easy subscription management
4. **In-Memory**: No external dependencies, works entirely in memory

**Usage Notes:**
- The `subscribe` method returns an unsubscribe function for removing subscriptions
- Multiple subscribers can listen to the same event
- The `publish` method broadcasts data to all subscribers of that event
- Data type is `any` for flexibility, but you could make it generic for better type safety in production code

Here's a Go function that checks if two strings are anagrams, ignoring case and spaces:

```go
package main

import (
	"fmt"
	"strings"
	"unicode"
)

// AreAnagrams checks whether two strings are anagrams of each other,
// ignoring case and spaces. The function normalizes both strings by
// converting to lowercase and removing all whitespace characters, then
// compares the frequency of each character. If both strings have the
// same character counts, they are anagrams.
//
// The approach:
// 1. Normalize both strings (lowercase, remove spaces)
// 2. Count character frequencies for each string
// 3. Compare the frequency maps
//
// Example:
// result := AreAnagrams("Listen", "Silent")
// fmt.Println(result) // Output: true
func AreAnagrams(s1, s2 string) bool {
	// Normalize strings: lowercase and remove spaces
	normalize := func(s string) string {
		var sb strings.Builder
		for _, r := range strings.ToLower(s) {
			if !unicode.IsSpace(r) {
				sb.WriteRune(r)
			}
		}
		return sb.String()
	}

	norm1 := normalize(s1)
	norm2 := normalize(s2)

	// If lengths differ after normalization, they can't be anagrams
	if len(norm1) != len(norm2) {
		return false
	}

	// Count character frequencies for first string
	counts := make(map[rune]int)
	for _, r := range norm1 {
		counts[r]++
	}

	// Decrement counts for second string
	for _, r := range norm2 {
		counts[r]--
		if counts[r] < 0 {
			return false // More of this character in s2 than s1
		}
	}

	// If we get here, all counts should be zero
	return true
}

func main() {
	// Example usage
	result := AreAnagrams("Listen", "Silent")
	fmt.Println(result) // Output: true

	result2 := AreAnagrams("Hello World", "World Hello")
	fmt.Println(result2) // Output: true

	result3 := AreAnagrams("Hello", "World")
	fmt.Println(result3) // Output: false
}
```

**Key points about the implementation:**

1. **Normalization**: Converts both strings to lowercase and removes all whitespace characters (spaces, tabs, newlines, etc.)
2. **Efficiency**: Uses a single map to track character counts - incrementing for the first string and decrementing for the second
3. **Early exit**: Returns `false` immediately if lengths differ after normalization, or if a character count goes negative
4. **Unicode support**: Works with Unicode characters, not just ASCII

**Time Complexity**: O(n) where n is the length of the strings
**Space Complexity**: O(k) where k is the number of unique characters in the strings

