/**
 * Deep clone a plain object or array
 * @param {Object|Array} source - The object/array to clone
 * @returns {Object|Array} - A deep clone of the source
 * 
 * LIMITATION: This function only handles plain objects, arrays, and primitive values.
 * It does NOT handle:
 * - Functions (they're copied by reference)
 * - Circular references (would cause infinite recursion)
 * - Special objects like Date, RegExp, Map, Set, etc.
 * - Class instances (they lose their prototype)
 */
function deepClone(source) {
  // Handle primitive types and null
  if (source === null || typeof source !== 'object') {
    return source;
  }

  // Handle arrays
  if (Array.isArray(source)) {
    return source.map(item => deepClone(item));
  }

  // Handle plain objects
  const clone = {};
  for (const key in source) {
    // Only copy own enumerable properties
    if (Object.prototype.hasOwnProperty.call(source, key)) {
      clone[key] = deepClone(source[key]);
    }
  }
  return clone;
}

