```rust
/// Performs a binary search on a sorted vector of i32 values.
/// 
/// Returns `Some(index)` if the target value is found in the vector,
/// or `None` if the value is not present.
/// 
/// # Arguments
/// 
/// * `sorted_vec` - A sorted vector of i32 values (must be sorted in ascending order)
/// * `target` - The value to search for
/// 
/// # Returns
/// 
/// * `Option<usize>` - The index of the target if found, otherwise `None`
/// 
/// # Complexity
/// 
/// Time: O(log n) where n is the length of the vector
/// Space: O(1) - iterative approach
pub fn binary_search(sorted_vec: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = sorted_vec.len();

    while left < right {
        let mid = left + (right - left) / 2;

        if sorted_vec[mid] == target {
            return Some(mid);
        } else if sorted_vec[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    None
}

