Here's a simple singly linked list implementation in Go:

```go
package main

import "fmt"

// Node represents a single element in the linked list
type Node struct {
    value int
    next  *Node
}

// LinkedList is a singly linked list that stores integers.
// It supports insertion at the end and conversion to a slice.
type LinkedList struct {
    head *Node
    tail *Node
    size int
}

// Insert adds a new value to the end of the linked list.
func (l *LinkedList) Insert(value int) {
    newNode := &Node{value: value}

    if l.head == nil {
        l.head = newNode
        l.tail = newNode
    } else {
        l.tail.next = newNode
        l.tail = newNode
    }
    l.size++
}

// ToSlice converts the linked list to a slice of integers.
// Returns an empty slice if the list is empty.
func (l *LinkedList) ToSlice() []int {
    result := make([]int, 0, l.size)
    current := l.head

    for current != nil {
        result = append(result, current.value)
        current = current.next
    }

    return result
}

func main() {
    // Example usage:
    // list := &LinkedList{}
    // list.Insert(1)
    // list.Insert(2)
    // list.Insert(3)
    // fmt.Println(list.ToSlice()) // Output: [1 2 3]

    list := &LinkedList{}
    list.Insert(1)
    list.Insert(2)
    list.Insert(3)
    fmt.Println(list.ToSlice()) // Output: [1 2 3]
}
```

**Key features of this implementation:**

1. **`Node` struct**: Contains a value and a pointer to the next node
2. **`LinkedList` struct**: Tracks head, tail, and size for efficient operations
3. **`Insert(value int)`**: Adds a new node at the end in O(1) time by maintaining a tail pointer
