Here's a Go function that parses a simple key=value config file format:

```go
// ParseConfig parses a simple key=value configuration format.
//
// Expected format:
//   - One key=value pair per line
//   - Lines starting with '#' are treated as comments and ignored
//   - Blank lines are ignored
//   - Keys and values are trimmed of surrounding whitespace
//   - Lines without '=' are skipped (malformed lines are ignored)
//   - The first '=' in a line separates key from value
//   - Duplicate keys: the last occurrence wins
//
// Example:
//
//	# This is a comment
//	server=localhost
//	port=8080
//	debug=true
//
//	# Another comment
//	path=/var/log/app.log
//
// Returns a map containing the parsed key-value pairs.
func ParseConfig(data string) map[string]string {
	config := make(map[string]string)

	// Split the input into lines
	lines := strings.Split(data, "\n")

	for _, line := range lines {
		// Trim whitespace from the line
		trimmedLine := strings.TrimSpace(line)

		// Skip empty lines and comments
		if trimmedLine == "" || strings.HasPrefix(trimmedLine, "#") {
			continue
		}

		// Find the first '=' to separate key and value
		eqIndex := strings.Index(trimmedLine, "=")
		if eqIndex == -1 {
			// Skip lines without '=' (malformed)
			continue
		}

		// Extract key and value, trimming whitespace
		key := strings.TrimSpace(trimmedLine[:eqIndex])
		value := strings.TrimSpace(trimmedLine[eqIndex+1:])

		// Skip empty keys (but allow empty values)
		if key == "" {
			continue
		}

		// Store in the map (last occurrence wins for duplicates)
		config[key] = value
	}

	return config
}
```

