/**
 * A simple in-memory pub/sub (publish-subscribe) event system.
 * Allows subscribers to register callbacks for specific events and
 * publishers to broadcast data to all subscribers of that event.
 */
class PubSub {
  // Map to store event names and their associated subscriber callbacks
  private events: Map<string, Function[]> = new Map();

  /**
   * Subscribe a callback to a specific event
   * @param event - The event name to subscribe to
   * @param callback - The function to call when the event is published
   * @returns An unsubscribe function to remove the subscription
   */
  subscribe(event: string, callback: Function): () => void {
    // Get existing subscribers for this event, or create a new array
    const subscribers = this.events.get(event) || [];
    subscribers.push(callback);
    this.events.set(event, subscribers);

    // Return an unsubscribe function for easy cleanup
    return () => {
      const currentSubscribers = this.events.get(event);
      if (currentSubscribers) {
        const index = currentSubscribers.indexOf(callback);
        if (index > -1) {
          currentSubscribers.splice(index, 1);
          this.events.set(event, currentSubscribers);
        }
      }
    };
  }

  /**
   * Publish an event with data to all subscribers
   * @param event - The event name to publish
   * @param data - The data to pass to all subscriber callbacks
   */
  publish(event: string, data: any): void {
    const subscribers = this.events.get(event);
    if (subscribers) {
      // Call each subscriber with the published data
      subscribers.forEach(callback => callback(data));
    }
  }
}

