```go
// AreAnagrams checks whether two strings are anagrams of each other,
// ignoring case and spaces. It uses a frequency counter approach:
// 1. Normalize both strings by converting to lowercase and removing spaces
// 2. Count character frequencies in the first string
// 3. Decrement frequencies for characters in the second string
// 4. If all frequencies are zero, the strings are anagrams
//
// Time complexity: O(n) where n is the length of the longer string
// Space complexity: O(k) where k is the number of unique characters
func AreAnagrams(s1, s2 string) bool {
	// Normalize strings: lowercase and remove spaces
	normalize := func(s string) string {
		result := make([]rune, 0, len(s))
		for _, r := range strings.ToLower(s) {
			if r != ' ' {
				result = append(result, r)
			}
		}
		return string(result)
	}

	norm1 := normalize(s1)
	norm2 := normalize(s2)

	// If lengths differ after normalization, they can't be anagrams
	if len(norm1) != len(norm2) {
		return false
	}

	// Count character frequencies
	freq := make(map[rune]int)
	for _, r := range norm1 {
		freq[r]++
	}

	// Decrement frequencies for second string
	for _, r := range norm2 {
		freq[r]--
		if freq[r] < 0 {
			return false // More occurrences of this character in s2
		}
	}

	// All frequencies should be zero if they're anagrams
	for _, count := range freq {
		if count != 0 {
			return false
		}
	}

	return true
}

// Example usage:
// result := AreAnagrams("Listen", "Silent")
// fmt.Println(result) // Output: true
//
// result2 := AreAnagrams("Astronomer", "Moon starer")
// fmt.Println(result2) // Output: true
//
// result3 := AreAnagrams("Hello", "World")
// fmt.Println(result3) // Output: false
```

The function works by:
1. **Normalizing** both strings (converting to lowercase and removing spaces)
2. **Counting character frequencies** in the first string using a map
3. **Decrementing frequencies** for characters in the second string
4. **Verifying** that all frequencies end up at zero

This approach handles Unicode characters properly and has linear time complexity. The early exit conditions (length mismatch and negative frequency) make it efficient for non-anagram cases.

