Here's a JavaScript function that deep-clones plain objects and arrays without using `JSON.stringify/parse`:

```javascript
/**
 * Deep clone a plain object or array
 * @param {Object|Array} source - The object/array to clone
 * @returns {Object|Array} - A deep clone of the source
 * 
 * LIMITATION: This function only handles plain objects, arrays, and primitive values.
 * It does NOT handle:
 * - Functions (they're copied by reference)
 * - Circular references (would cause infinite recursion)
 * - Special objects like Date, RegExp, Map, Set, etc.
 * - Class instances (they lose their prototype)
 */
function deepClone(source) {
  // Handle primitive types and null
  if (source === null || typeof source !== 'object') {
    return source;
  }

  // Handle arrays
  if (Array.isArray(source)) {
    return source.map(item => deepClone(item));
  }

  // Handle plain objects
  const clone = {};
  for (const key in source) {
    // Only copy own enumerable properties
    if (Object.prototype.hasOwnProperty.call(source, key)) {
      clone[key] = deepClone(source[key]);
    }
  }
  return clone;
}

// Example with nested object
const original = {
  name: "John",
  age: 30,
  address: {
    street: "123 Main St",
    city: "New York",
    coordinates: {
      lat: 40.7128,
      lng: -74.0060
    }
  },
  hobbies: ["reading", "coding", "hiking"],
  nestedArray: [
    { id: 1, data: [1, 2, 3] },
    { id: 2, data: [4, 5, 6] }
  ]
};

const cloned = deepClone(original);

// Test that it's a true deep clone
console.log("Original:", original);
console.log("Cloned:", cloned);

// Verify they're different objects
console.log("Same object?", original === cloned); // false
console.log("Same address?", original.address === cloned.address); // false
console.log("Same nested array?", original.nestedArray === cloned.nestedArray); // false
console.log("Same nested array element?", original.nestedArray[0] === cloned.nestedArray[0]); // false

// Modify the clone to prove independence
cloned.address.city = "Los Angeles";
cloned.nestedArray[0].data[0] = 999;
cloned.hobbies.push("gaming");

console.log("\nAfter modifying clone:");
console.log("Original city:", original.address.city); // "New York"
console.log("Cloned city:", cloned.address.city); // "Los Angeles"
console.log("Original first data:", original.nestedArray[0].data[0]); // 1
console.log("Cloned first data:", cloned.nestedArray[0].data[0]); // 999
console.log("Original hobbies:", original.hobbies); // ["reading", "coding", "hiking"]
console.log("Cloned hobbies:", cloned.hobbies); // ["reading", "coding", "hiking", "gaming"]
